sys_script.script:
(function executeRule(current, previous) {

    var deptName = "";

    switch (current.getDisplayValue('category')) {

        case "water_leakage":
            deptName = "Water Department";
            break;

        case "garbage":
            deptName = "Sanitation Department";
            break;

        case "street_light":
            deptName = "Electrical Department";
            break;

        case "road_damage":
            deptName = "Roads Department";
            break;

        case "drainage":
            deptName = "Sanitation Department";
            break;

        case "electricity":
            deptName = "Electrical Department";
            break;

        case "public_park":
            deptName = "Parks Department";
            break;
    }

    if (deptName != "") {

        var dept = new GlideRecord('x_1972253_citize_0_department');
        dept.addQuery('department_name', deptName);
        dept.query();

        if (dept.next()) {
            current.assigned_department = dept.getUniqueValue();
			current.ai_routed=true;
        }
		else{
			current.ai_routed=false;
		}

    }

})(current, previous);
